/// Relative Ziv gate for the middle [`sinpi_dd`] tier: the double-double π
/// truncates at ≈2⁻¹⁰⁹ and the kernel/multiply roundings sit near 2⁻¹⁰⁴, so
/// `2⁻¹⁰¹` bounds the tier with margin (certified by
/// `ziv_soundness::sinpi_dd_tier_is_sound`); the rare survivors take the
/// 128-bit `Dint` kernels.
const SINPI_DD_EPS: f64 = crate::exp2i(-101);

/// `(sin, cos)` at the grid angle `s·π/2048` as loose double-doubles — a port
/// of CORE-MATH sinpi's `sincosn` two-level table.  `s` is taken modulo 4096
/// through two's-complement bit logic (works for negative `s` unchanged): the
/// low ten bits index within a quadrant (reflected in odd quadrants), split
/// into the π/64 level ([`SINCOSN_SN`], cosine by complement) and the π/2048
/// level ([`SINCOSN_SM`]/[`SINCOSN_CM`]); the angle-addition cross products of
/// the ≤25-bit table highs are exact, so one Fast2Sum per component
/// renormalizes the pair.  Bits 11/12 of `s` supply the half-turn signs.
#[inline]
pub fn sincosn(s: i64) -> (DoubleDouble, DoubleDouble) {
    let j0 = s & 0x3ff;
    let it = -((s >> 10) & 1); // odd quadrant: reflect j → 1024 − j
    let j = (!it & j0) - (it << 10) - (it & j0);
    let is = (j >> 5) as usize;
    let jm = (j & 0x1f) as usize;
    // Branchless sign bits: the quadrant bits flip the components by XOR on
    // the sign bit (a 50/50 data-dependent branch would mispredict on random
    // input).
    let ssgn = (((s >> 11) & 1) as u64) << 63;
    let csgn = ((((s + 1024) >> 11) & 1) as u64) << 63;

    // SAFETY: `j ∈ [0, 1024]` by the reflection above, so `is ∈ [0, 32]` and
    // `jm ∈ [0, 31]`; the compiler cannot see the range, and the elided bounds
    // checks are worth ≈1 ns on the hot path.
    let (sb, cb, sm, cm) = unsafe {
        (
            *SINCOSN_SN.get_unchecked(is),      // sin at is·π/64
            *SINCOSN_SN.get_unchecked(32 - is), // cos at is·π/64, by complement
            *SINCOSN_SM.get_unchecked(jm),      // sin at jm·π/2048
            *SINCOSN_CM.get_unchecked(jm),      // cos at jm·π/2048
        )
    };

    // Angle addition with exact high×high products (≤25-bit factors).
    let sbf = sb.high + sb.low;
    let cbf = cb.high + cb.low;
    // Not FMA sites: the ≤25-bit high×high products are exact, and the error
    // budget assumes each term rounds on its own.
    #[allow(clippy::suboptimal_flops)]
    let ch = cb.high * cm.high - sb.high * sm.high;
    #[allow(clippy::suboptimal_flops)]
    let cl = cm.high * cb.low - sm.high * sb.low + (cbf * cm.low - sbf * sm.low);
    #[allow(clippy::suboptimal_flops)]
    let sh = sb.high * cm.high + cb.high * sm.high;
    #[allow(clippy::suboptimal_flops)]
    let sl = sm.high * cb.low + cm.high * sb.low + (cbf * sm.low + sbf * cm.low);

    let (s2, c2) = (fast_sum(sh, sl), fast_sum(ch, cl));
    (
        DoubleDouble {
            high: f64::from_bits(s2.high.to_bits() ^ ssgn),
            low: f64::from_bits(s2.low.to_bits() ^ ssgn),
        },
        DoubleDouble {
            high: f64::from_bits(c2.high.to_bits() ^ csgn),
            low: f64::from_bits(c2.low.to_bits() ^ csgn),
        },
    )
}

/// Ziv gate for [`sinpi`]'s grid fast leg, an *absolute* bound on the
/// correction `r` (everything below the leading table word): the exact `u`
/// keeps the polynomial terms clean, so the slip is a handful of f64
/// roundings at `r`'s ≈2⁻⁶³ ulp scale.  Certified with ≥2× margin by
/// `ziv_soundness::sinpi_fast_leg_is_sound`; near-zero table words (inputs
/// within ≈2⁻⁹ of an integer) never certify and take the `Dint` tier.
const SINPIN_ERR: f64 = 5.5e-19;

/// Sine of π·x
///
/// Follows C23's special-value contract: `sinpi(±0) = ±0`, `sinpi(n) =
/// copysign(0, x)` for every integer `n` (parity-free), `sinpi(±(2k + ½)) =
/// ±1` and `sinpi(±(2k + 1 + ½)) = ∓1` exactly, and ±∞/NaN → NaN.
///
/// Mirrors CORE-MATH's `cr_sinpi` fast path: an integer reduction of the
/// signed mantissa puts the grid index (1/2048 half-turns) and the exact
/// residual bits in two shifts, [`sincosn`]'s two's-complement bit logic
/// folds quadrants and signs, and short plain-f64 residual polynomials feed
/// the absolute Ziv gate.  The small band `|x| ≤ 0x1.2p−5` keeps relative
/// accuracy through a double-double `π·x` with a cubic correction.
/// Straddles fall to the relative-gated [`sinpi_dd`] middle tier, and the
/// rare survivors to the 128-bit `Dint` sin/cos kernels (≈2⁻¹²⁵) — CORE-MATH
/// needs an exception database at this depth; the `Dint` tier does not.
#[must_use]
#[inline]
pub fn sinpi(x: f64) -> f64 {
    let ix = x.to_bits();
    let e = ((ix >> 52) & 0x7ff) as i64;

    // |x| ≥ 2⁴¹ (every value is a multiple of 1/2048), ±∞, NaN.
    if e >= 1064 {
        if e == 0x7ff {
            return if ix << 12 == 0 { f64::NAN } else { x + x };
        }
        if e > 1074 {
            return f64::copysign(0.0, x); // |x| ≥ 2⁵²: all integers
        }
        let sgn = (ix as i64) >> 63;
        let m = ((((ix & (u64::MAX >> 12)) | 1 << 52) as i64) ^ sgn) - sgn;
        // x·2048 is an exact integer here; two's complement keeps the sign.
        let iq = (m as u64).wrapping_shl((e - 1064) as u32);
        if iq & 2047 == 0 {
            return f64::copysign(0.0, x); // integer x
        }
        let (sg, _) = sincosn(iq as i64);
        return sg.high + sg.low; // exact grid point: the table is the answer
    }

    let ax = ix & (u64::MAX >> 1);
    // Small band |x| ≤ 0x1.2p−5: relative accuracy through double-double π·x.
    if ax <= 0x3fa2_0000_0000_0000 {
        if x == 0.0 {
            return x; // ±0 keeps its sign
        }
        // |x| < 2⁻⁵⁴: sin(πx) rounds as the product π·x.  Below 2⁻⁹⁷⁰ the
        // product is formed at 2¹⁰⁶ scale and folded down with one FMA so the
        // subnormal rounding happens exactly once (CORE-MATH's fold).
        if ax < 0x3c90_0000_0000_0000 {
            if ax < (53 << 52) {
                let t = x * crate::exp2i(106);
                let zh = PI_DD.high * t;
                #[allow(clippy::suboptimal_flops)] // CORE-MATH's exact op sequence
                let zl = crate::fma(PI_DD.high, t, -zh) + PI_DD.low * t;
                let rs = (zh + zl) * crate::exp2i(-106);
                let rt = rs * crate::exp2i(106);
                return crate::fma((zh - rt) + zl, crate::exp2i(-106), rs);
            }
            let zh = PI_DD.high * x;
            #[allow(clippy::suboptimal_flops)] // CORE-MATH's exact op sequence
            let zl = crate::fma(PI_DD.high, x, -zh) + PI_DD.low * x;
            return zh + zl;
        }
        // π·x as a double-double plus the odd Taylor correction.  The gate is
        // CORE-MATH's width with the x²-term half again wider — the measured
        // slip reaches 0.58× the original window, short of the 2× margin
        // `ziv_soundness::sinpi_small_band_is_sound` certifies.
        let zh = PI_DD.high * x;
        #[allow(clippy::suboptimal_flops)] // CORE-MATH's exact op sequence
        let zl = crate::fma(PI_DD.high, x, -zh) + PI_DD.low * x;
        let x2 = x * x;
        let x3 = x2 * x;
        let x4 = x2 * x2;
        let eps = x * crate::fast_mul_add(x2, 1.5 * crate::exp2i(-47), crate::exp2i(-102));
        #[allow(clippy::suboptimal_flops)] // CORE-MATH's certified splitting
        let zl = zl
            + x3 * ((SINPI_SMALL_C[0] + x2 * SINPI_SMALL_C[1])
                + x4 * (SINPI_SMALL_C[2] + x2 * SINPI_SMALL_C[3]));
        let lb = (zl - eps) + zh;
        let ub = (zl + eps) + zh;
        if lb == ub {
            return lb;
        }
        return sinpi_accurate(x);
    }

    // Main band 0x1.2p−5 < |x| < 2⁴¹ (e ∈ [1018, 1063]): integer reduction.
    let m0 = (ix & (u64::MAX >> 12)) | 1 << 52;
    let si = e - 1011;
    if si >= 0 && m0.wrapping_shl((si + 1) as u32) == 0 {
        // x is an integer or half-integer (si ≥ 7 in this band).
        if m0.wrapping_shl(si as u32) == 0 {
            return f64::copysign(0.0, x);
        }
        // |x| mod 2 = ½ → ±1; = 3/2 → ∓1.
        let t = m0.wrapping_shl((si - 1) as u32) >> 63;
        return if t == 0 {
            f64::copysign(1.0, x)
        } else {
            -f64::copysign(1.0, x)
        };
    }

    let sgn = (ix as i64) >> 63;
    let m = ((m0 as i64) ^ sgn) - sgn;
    let s = 1063 - e; // 0..=45
    let iq = ((m >> s) + 1) >> 1; // round(x·2048) in 1/2048 half-turns
    // The residual keeps all its bits: the shifted-out top is the integer
    // part already in `iq`.  The i64 → f64 rounding of the lowest bits is
    // inside the gate's budget.
    let k = (m as u64).wrapping_shl((e - 1000) as u32) as i64;
    let z = k as f64;
    let z2 = z * z;
    let fs = crate::fast_mul_add(
        z2,
        crate::fast_mul_add(z2, SINPI_ZS[2], SINPI_ZS[1]),
        SINPI_ZS[0],
    );
    let fc = crate::fast_mul_add(z2, SINPI_ZC[1], SINPI_ZC[0]);
    let (sg, cg) = sincosn(iq);
    #[allow(clippy::suboptimal_flops)] // the remaining splits are the certified budget
    let r = crate::fast_mul_add(cg.high, z * fs, sg.low + sg.high * (z2 * fc));
    let lb = (r - SINPIN_ERR) + sg.high;
    let ub = (r + SINPIN_ERR) + sg.high;
    if lb == ub {
        return lb;
    }

    // Middle tier: the ≈2⁻¹⁰⁴ double-double kernel, relative-gated.
    let v = sinpi_dd(x);
    let eps = v.high.abs() * SINPI_DD_EPS;
    let lo = v.high + (v.low - eps);
    let hi = v.high + (v.low + eps);
    if lo == hi {
        return lo;
    }
    sinpi_accurate(x)
}

/// Final [`sinpi`] tier: `2x − q` is exact (Sterbenz), so `π·(x − q/2)`
/// reaches the 128-bit sin/cos kernels at ≈2⁻¹²⁵ relative — the double-double
/// π (≈2⁻¹⁰⁹) cannot split the corpus' hardest ties.  The quadrant selection
/// carries the sign; the result is normal (|x − round(x)| ≥ 2⁻⁵³ here, so the
/// magnitude is ≥ 2⁻⁵¹), which `to_f64` requires.
#[cold]
fn sinpi_accurate(x: f64) -> f64 {
    let q = (2.0 * x).round_ties_even();
    #[allow(clippy::suboptimal_flops)] // 2x is exact; the subtraction is Sterbenz
    let theta = Dint::from_f64(2.0 * x - q).mul(&PIO2_DINT); // π(x − q/2) ∈ [−π/4, π/4]
    // SAFETY: |q| ≤ 2⁵³ fits an `i64`.
    let w = match unsafe { q.to_int_unchecked::<i64>() } & 3 {
        0 => sin_dint(&theta),
        1 => cos_dint(&theta),
        2 => neg_dint(sin_dint(&theta)),
        _ => neg_dint(cos_dint(&theta)),
    };
    w.to_f64()
}

/// Taylor coefficients of `(cos(πx) − 1)/x²` for the small band
/// `|x| ≤ 2⁻¹²` (CORE-MATH cospi's `c`, verbatim).
const COSPI_SMALL_C: [f64; 4] = [
    -4.934_802_200_544_677,
    4.058_712_126_397_995,
    -1.335_262_715_026_094_7,
    0.235_267_632_957_854_3,
];

/// Cosine of π·x
///
/// Follows C23's special-value contract: `cospi(±0) = 1`, `cospi(k + ½) = +0`
/// for every half-integer (sign-free), integers give ±1 by parity, and
/// ±∞/NaN → NaN.  The structure mirrors [`sinpi`] — the quarter-turn shift
/// rides the grid index (`+2048` before halving), the mantissa stays unsigned
/// (cosine is even), and the cross term flips sign — with the same
/// [`sincosn`] table, residual polynomials, and tier ladder.  The fast gate is
/// CORE-MATH's residual-proportional `z·2⁻¹²³` plus an absolute 2⁻⁷⁷ floor
/// for the table pair's own ≈2⁻⁷⁹ accuracy near grid points — without the
/// floor the slope window vanishes there while the table error does not
/// (certified at ≥2× margin by `ziv_soundness::cospi_fast_leg_is_sound`).
#[must_use]
#[inline]
pub fn cospi(x: f64) -> f64 {
    let ix = x.to_bits();
    let ax = ix & (u64::MAX >> 1);
    let e = (ax >> 52) as i64;

    // |x| ≥ 2⁴¹ (every value is a multiple of 1/2048), ±∞, NaN.
    if e >= 1064 {
        if e == 0x7ff {
            return if ix << 12 == 0 { f64::NAN } else { x + x };
        }
        if e > 1075 {
            return 1.0; // |x| ≥ 2⁵³: all even integers
        }
        let m = (ix & (u64::MAX >> 12)) | 1 << 52;
        // |x|·2048 + a quarter turn, exact; evenness needs no sign fold.
        let iq = m.wrapping_shl((e - 1064) as u32).wrapping_add(1024);
        if iq & 2047 == 0 {
            return 0.0; // half-integer x: +0 always
        }
        let (sg, _) = sincosn(iq as i64);
        return sg.high + sg.low; // exact grid point: the table is the answer
    }

    // Small band |x| ≤ 2⁻¹²: even Taylor around 1.
    if ax <= 0x3f30_0000_0000_0000 {
        // cos(πx) rounds to 1 for (πx)²/2 ≤ 2⁻⁵⁴ (the expression keeps
        // CORE-MATH's shape; round-to-nearest folds it to 1.0).
        if ax <= 0x3e2c_cf64_29be_6621 {
            return 1.0 - crate::exp2i(-55);
        }
        let x2 = x * x;
        let x4 = x2 * x2;
        let eps = x2 * 8.659_739_592_076_221e-15;
        #[allow(clippy::suboptimal_flops)] // CORE-MATH's certified splitting
        let p = x2
            * ((COSPI_SMALL_C[0] + x2 * COSPI_SMALL_C[1])
                + x4 * (COSPI_SMALL_C[2] + x2 * COSPI_SMALL_C[3]));
        let lb = (p - eps) + 1.0;
        let ub = (p + eps) + 1.0;
        if lb == ub {
            return lb;
        }
        return cospi_accurate(x);
    }

    // Main band 2⁻¹² < |x| < 2⁴¹ (e ∈ [1011, 1063]): integer reduction.
    let m = (ix & (u64::MAX >> 12)) | 1 << 52;
    let si = e - 1011;
    if si >= 0 && m.wrapping_shl(si as u32) == 1 << 63 {
        return 0.0; // half-integer x: +0 always
    }

    let s = 1063 - e; // 0..=52
    let iq = ((((m >> s).wrapping_add(2048)) & 8191).wrapping_add(1)) >> 1;
    let k = m.wrapping_shl((e - 1000) as u32) as i64;
    let z = k as f64;
    let z2 = z * z;
    let fs = crate::fast_mul_add(
        z2,
        crate::fast_mul_add(z2, SINPI_ZS[2], SINPI_ZS[1]),
        SINPI_ZS[0],
    );
    let fc = crate::fast_mul_add(z2, SINPI_ZC[1], SINPI_ZC[0]);
    let (sg, cg) = sincosn(iq as i64);
    let er = crate::fast_mul_add(z.abs(), crate::exp2i(-123), crate::exp2i(-77));
    #[allow(clippy::suboptimal_flops)] // the remaining splits are the certified budget
    let r = crate::fast_mul_add(cg.high, z * fs, sg.low + sg.high * (z2 * fc));
    let lb = (r - er) + sg.high;
    let ub = (r + er) + sg.high;
    if lb == ub {
        return lb;
    }

    // Middle tier: the ≈2⁻¹⁰⁴ double-double kernel, relative-gated.
    let v = cospi_dd(x);
    let eps = v.high.abs() * SINPI_DD_EPS;
    let lo = v.high + (v.low - eps);
    let hi = v.high + (v.low + eps);
    if lo == hi {
        return lo;
    }
    cospi_accurate(x)
}

/// `cos(πx)` as a double-double for `|x| < 2⁵²` — [`sinpi_dd`]'s quadrant
/// selection rotated a quarter turn.
#[inline]
fn cospi_dd(x: f64) -> DoubleDouble {
    let q = (2.0 * x).round_ties_even();
    let theta = PI_DD * (x - q * 0.5);
    // SAFETY: `|x| < 2⁵²`, so `|q| < 2⁵³` fits an `i64`.
    match unsafe { q.to_int_unchecked::<i64>() } & 3 {
        0 => cos_kernel(theta),
        1 => neg(sin_kernel(theta)),
        2 => neg(cos_kernel(theta)),
        _ => sin_kernel(theta),
    }
}

/// Final [`cospi`] tier — [`sinpi_accurate`] rotated a quarter turn.
#[cold]
fn cospi_accurate(x: f64) -> f64 {
    let q = (2.0 * x).round_ties_even();
    #[allow(clippy::suboptimal_flops)] // 2x is exact; the subtraction is Sterbenz
    let theta = Dint::from_f64(2.0 * x - q).mul(&PIO2_DINT); // π(x − q/2) ∈ [−π/4, π/4]
    // SAFETY: |q| ≤ 2⁵³ fits an `i64`.
    let w = match unsafe { q.to_int_unchecked::<i64>() } & 3 {
        0 => cos_dint(&theta),
        1 => neg_dint(sin_dint(&theta)),
        2 => neg_dint(cos_dint(&theta)),
        _ => sin_dint(&theta),
    };
    w.to_f64()
}

/// Sine
#[must_use]
#[inline]
pub fn sin(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: sin(x) = x to within ½ ulp; preserves ±0.
    if x.abs() < SMALL {
        return x;
    }

    let (q, r) = rem_pio2(x.abs());

    // sin(|x|): even quadrants use sin(r), odd use cos(r); q&2 sets the sign.
    // Only the selected half is computed (vs. both for `sincos`).
    let need_cos = q & 1 != 0;
    let negate = q & 2 != 0;
    let signed = |v: DoubleDouble| if negate { neg(v) } else { v };

    let fast = signed(if need_cos {
        cos_kernel_fast(r)
    } else {
        sin_kernel_fast(r)
    });
    let magnitude = ziv(fast).unwrap_or_else(|| {
        // Accurate `Dint` path: re-reduce to a 128-bit `r` and round once.
        let (q, r) = payne_hanek_dint(x.abs());
        let v = if q & 1 != 0 {
            cos_dint(&r)
        } else {
            sin_dint(&r)
        };
        let v = if q & 2 != 0 { neg_dint(v) } else { v };
        v.to_f64()
    });

    if x.is_sign_negative() {
        -magnitude
    } else {
        magnitude
    }
}

/// Cosine
#[must_use]
#[inline]
pub fn cos(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: cos(x) = 1 to within ½ ulp.
    if x.abs() < SMALL {
        return 1.0;
    }

    let (q, r) = rem_pio2(x.abs());

    // cos(|x|): even quadrants use cos(r), odd use sin(r); (q+1)&2 sets the sign.
    let need_sin = q & 1 != 0;
    let negate = q.wrapping_add(1) & 2 != 0;
    let signed = |v: DoubleDouble| if negate { neg(v) } else { v };

    let fast = signed(if need_sin {
        sin_kernel_fast(r)
    } else {
        cos_kernel_fast(r)
    });
    ziv(fast).unwrap_or_else(|| {
        // Accurate `Dint` path: re-reduce to a 128-bit `r` and round once.
        let (q, r) = payne_hanek_dint(x.abs());
        let v = if q & 1 != 0 {
            sin_dint(&r)
        } else {
            cos_dint(&r)
        };
        let v = if q.wrapping_add(1) & 2 != 0 {
            neg_dint(v)
        } else {
            v
        };
        v.to_f64()
    })
}

/// Simultaneous sine and cosine
#[must_use]
#[inline]
pub fn sincos(x: f64) -> (f64, f64) {
    if !x.is_finite() {
        return (f64::NAN, f64::NAN);
    }

    // |x| < 2⁻²⁷: (sin, cos) = (x, 1) to within ½ ulp; preserves ±0 in sin.
    if x.abs() < SMALL {
        return (x, 1.0);
    }

    let (q, r) = rem_pio2(x.abs());

    let (s, c) = sin_cos_kernel_fast(r);
    // Both components must pass the gate; otherwise recompute both accurately.
    let (sin, cos) = match (ziv(select_sin(q, s, c)), ziv(select_cos(q, s, c))) {
        (Some(sin), Some(cos)) => (sin, cos),
        _ => {
            // Accurate `Dint` path: re-reduce to a 128-bit `r` and round each once.
            let (q, r) = payne_hanek_dint(x.abs());
            let (s, c) = sin_cos_dint(&r);
            (
                select_sin_dint(q, s, c).to_f64(),
                select_cos_dint(q, s, c).to_f64(),
            )
        }
    };

    let sin = if x.is_sign_negative() { -sin } else { sin };
    (sin, cos)
}

/// Tangent
#[must_use]
#[inline]
pub fn tan(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: tan(x) = x to within ½ ulp; preserves ±0.
    if x.abs() < SMALL {
        return x;
    }

    let (q, r) = rem_pio2(x.abs());

    // tan has period π, so tan(|x|) = tan(r) for even quadrants and −cot(r) =
    // −1/tan(r) for odd ones — one kernel, a reciprocal only half the time.
    let t = tan_kernel_fast(r);
    let fast = if q & 1 == 0 {
        t
    } else {
        // −1/t leanly: seed `y = −1/t.high` (the inner FMA's cancellation is
        // exact), fold `t.low` into the residual `e = 1 + y·t`, and take
        // `y·(1 + e)` — dropping `y·e²` ≈ 2⁻¹⁰⁴ relative, noise to the 2⁻⁵⁹
        // gate.  The full Newton `recip` (a double-double multiply, add, and
        // multiply on top of the divide) buys accuracy the gate cannot use.
        let y = -1.0 / t.high;
        let e = crate::fma(y, t.low, crate::fma(y, t.high, 1.0));
        DoubleDouble {
            high: y,
            low: y * e,
        }
    };
    let magnitude = ziv(fast).unwrap_or_else(|| {
        // Accurate `Dint` path: the sin/cos pair ratio in 128-bit fixed point.
        let (q, r) = payne_hanek_dint(x.abs());
        let (s, c) = sin_cos_dint(&r);
        let num = select_sin_dint(q, s, c);
        let den = select_cos_dint(q, s, c);
        num.mul(&recip_dint(&den)).to_f64()
    });

    if x.is_sign_negative() {
        -magnitude
    } else {
        magnitude
    }
}

/// The Fast2Sum-based folds of [`tan_kernel_fast`] need `|a| ≥ |b|`; prove the
/// orderings from coefficient-magnitude bounds at `v = w = (π/4)²`, the
/// octant's edge, with 2× margin (cf. the same-named module in `erf.rs`).
#[cfg(test)]
mod fold_ordering {
    use super::*;

    /// `sin_part_fast` / `cos_part_fast`: `1 ⊕ u·c₁ ⊕ u²·c₂ ⊕ u³·tail` with
    /// `u = r² ≤ (π/4)²`.
    #[test]
    fn sin_cos_leads() {
        let umax = core::f64::consts::FRAC_PI_4.powi(2) * 1.0001;
        let u2max = umax * umax;
        let u3max = umax.powi(3);
        let tail_mag = |tail: &[f64]| {
            tail.iter()
                .rev()
                .fold(0.0, |acc, c| crate::fast_mul_add(acc, umax, c.abs()))
        };

        for (c1, c2, tail) in [
            (
                NEG_FRAC_1_6.high.abs() + NEG_FRAC_1_6.low.abs(),
                FRAC_1_120.high + FRAC_1_120.low.abs(),
                &SIN_TAIL,
            ),
            (0.5, FRAC_1_24.high + FRAC_1_24.low.abs(), &COS_TAIL),
        ] {
            assert!(umax * c1 <= 0.5);
            let lead_min = 1.0 - umax * c1;
            assert!(u2max * c2 <= 0.5 * lead_min);
            let lead2_min = lead_min - u2max * c2;
            assert!(u3max * tail_mag(tail) <= 0.5 * lead2_min);
        }
    }

    /// The table-driven `abs_sinpi_dd_lean` folds the residual polynomials with
    /// `add_ordered` (`S0 ⊕ d²·(…)` and `C1 ⊕ d²·(…)`), which needs the leading
    /// coefficient to dominate the higher-order remainder.  `|d| ≤ ½`, so check
    /// the remainder stays under half the lead there.
    #[test]
    fn sinpi_table_leads() {
        let d2max = 0.25_f64; // (½)²
        let mag = |c: DoubleDouble| c.high.abs() + c.low.abs();
        let poly_mag = |c: &[f64]| {
            c.iter()
                .rev()
                .fold(0.0, |acc, c| crate::fast_mul_add(acc, d2max, c.abs()))
        };
        // sin: |S0| ≥ |d²·(S1 + d²(S2 + d²·S3))|
        assert!(d2max * poly_mag(&[SINPI_S1.high, SINPI_S2, SINPI_S3]) <= 0.5 * mag(SINPI_S0));
        // cos: |C1| ≥ |d²·(C2 + d²·C3)|
        assert!(d2max * poly_mag(&[SINPI_C2, SINPI_C3]) <= 0.5 * mag(SINPI_C1));
    }

    #[test]
    fn tan_leads() {
        // Slack for the rounding of r and w = r·r at the octant edge.
        let wmax = core::f64::consts::FRAC_PI_4.powi(2) * 1.0001;
        let mag = |c: DoubleDouble| c.high.abs() + c.low.abs();

        // p0/p1/p2 = L₂ₖ ⊕ w·L₂ₖ₊₁
        for pair in TAN_LEADS.chunks(2) {
            assert!(wmax * mag(pair[1]) <= 0.5 * pair[0].high.abs());
        }

        // inner = p1 ⊕ w²·p2, outer = p0 ⊕ w²·inner, t = outer ⊕ v⁶·tail
        let w2max = wmax * wmax;
        let p2_mag = mag(TAN_LEADS[4]) + wmax * mag(TAN_LEADS[5]);
        let p1_min = TAN_LEADS[2].high - wmax * mag(TAN_LEADS[3]);
        assert!(w2max * p2_mag <= 0.5 * p1_min);
        let inner_mag = mag(TAN_LEADS[2]) + wmax * mag(TAN_LEADS[3]) + w2max * p2_mag;
        let p0_min = TAN_LEADS[0].high - wmax * mag(TAN_LEADS[1]);
        assert!(w2max * inner_mag <= 0.5 * p0_min);
        let tail_mag = TAN_TAIL
            .iter()
            .rev()
            .fold(0.0, |acc, c| crate::fast_mul_add(acc, wmax, c.abs()));
        let outer_min = p0_min - w2max * inner_mag;
        assert!(wmax.powi(3) * tail_mag <= 0.5 * outer_min);
    }
}

/// MPFR-certified soundness of `sinpi`'s lean-table-leg Ziv gate.  The gate may
/// only confirm a rounding when its relative half-width [`SINPI_ZIV_EPS`] truly
/// exceeds the leg's error.  Run with `--features mpfr`.
#[cfg(all(test, feature = "mpfr"))]
mod ziv_soundness {
    use super::*;
    use rug::Float;

    fn mix(i: u64) -> u64 {
        let mut z = i.wrapping_mul(0x2545_F491_4F6C_DD1D);
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// Worst `|leg(x) − sin(πx)| / SINPIN_ERR` for the main-band integer-
    /// reduction leg — its unrounded value is `sg.high + r` with `sg.high`
    /// exact, so the absolute gate is sound iff the slip stays below the
    /// window.  Value-uniform over `(0x1.2p−5, 4]` (every grid cell ×
    /// residual; sign-symmetric by construction); a ratio `< 0.5` certifies
    /// the 2× soundness margin.
    #[test]
    fn sinpi_fast_leg_is_sound() {
        let mut worst = 0.0f64;
        let mut worst_x = 0.5;
        for i in 0..30_000_000u64 {
            let x = 0.035_156_25 + mix(i) as f64 / (u64::MAX / 4) as f64;
            let ix = x.to_bits();
            let e = ((ix >> 52) & 0x7ff) as i64;
            let m = ((ix & (u64::MAX >> 12)) | 1 << 52) as i64;
            let s = 1063 - e;
            let iq = ((m >> s) + 1) >> 1;
            let k = (m as u64).wrapping_shl((e - 1000) as u32) as i64;
            let z = k as f64;
            let z2 = z * z;
            let fs = crate::fast_mul_add(
                z2,
                crate::fast_mul_add(z2, SINPI_ZS[2], SINPI_ZS[1]),
                SINPI_ZS[0],
            );
            let fc = crate::fast_mul_add(z2, SINPI_ZC[1], SINPI_ZC[0]);
            let (sg, cg) = sincosn(iq);
            let r = crate::fast_mul_add(cg.high, z * fs, sg.low + sg.high * (z2 * fc));
            let got = Float::with_val(250, sg.high) + Float::with_val(250, r);
            let truth = Float::with_val(250, x).sin_pi();
            let abs = Float::with_val(250, &got - &truth).abs().to_f64();
            let ratio = abs / SINPIN_ERR;
            if ratio > worst {
                worst = ratio;
                worst_x = x;
            }
        }
        println!("sinpi fast leg: worst |err|/gate = {worst:.4} at x={worst_x:e}");
        assert!(
            worst < 0.5,
            "sinpi gate covers only {:.2}× the slip at x={worst_x:e}",
            1.0 / worst
        );
    }

    /// Worst `|leg(x) − sin(πx)| / eps(x)` for the small band
    /// `(2⁻⁵⁴, 0x1.2p−5]`, representation-uniform so every binade appears.
    /// The gate width is CORE-MATH's `x·(x²·2⁻⁴⁷ + 2⁻¹⁰²)` with the x²-term
    /// widened 1.5× to restore the 2× margin.
    #[test]
    fn sinpi_small_band_is_sound() {
        let (lb, hb) = (0x3c90_0000_0000_0000u64, 0x3fa2_0000_0000_0000);
        let mut worst = 0.0f64;
        let mut worst_x = 0.5;
        for i in 0..30_000_000u64 {
            let x = f64::from_bits(lb + mix(i) % (hb - lb + 1));
            let zh = PI_DD.high * x;
            let zl = crate::fma(PI_DD.high, x, -zh) + PI_DD.low * x;
            let x2 = x * x;
            let x3 = x2 * x;
            let x4 = x2 * x2;
            let eps = x * crate::fast_mul_add(x2, 1.5 * crate::exp2i(-47), crate::exp2i(-102));
            let zl = zl
                + x3 * ((SINPI_SMALL_C[0] + x2 * SINPI_SMALL_C[1])
                    + x4 * (SINPI_SMALL_C[2] + x2 * SINPI_SMALL_C[3]));
            let got = Float::with_val(250, zh) + Float::with_val(250, zl);
            let truth = Float::with_val(250, x).sin_pi();
            let abs = Float::with_val(250, &got - &truth).abs().to_f64();
            let ratio = abs / eps;
            if ratio > worst {
                worst = ratio;
                worst_x = x;
            }
        }
        println!("sinpi small band: worst |err|/gate = {worst:.4} at x={worst_x:e}");
        assert!(
            worst < 0.5,
            "sinpi small-band gate covers only {:.2}× the slip at x={worst_x:e}",
            1.0 / worst
        );
    }

    /// Worst relative `|sinpi_dd(x) − sin(πx)| / (SINPI_DD_EPS·|high|)` over
    /// the middle tier's traffic: uniform across the band plus near-integer
    /// clusters (the fast leg's systematic straddles).  A ratio `< 0.5`
    /// certifies the 2× soundness margin.
    #[test]
    fn sinpi_dd_tier_is_sound() {
        let mut worst = 0.0f64;
        let mut worst_x = 0.5;
        for i in 0..20_000_000u64 {
            let h = mix(i);
            let x = if i & 1 == 0 {
                h as f64 / (u64::MAX / 4) as f64
            } else {
                // near-integer: k ± tiny, the fast leg's straddle population
                let k = ((h >> 32) % 8) as f64;
                let delta = f64::from_bits(0x3c90_0000_0000_0000 + (h & 0xF_FFFF_FFFF));
                if h & 16 == 0 { k + delta } else { k - delta }
            };
            if x == 0.0 || x.fract() == 0.0 {
                continue;
            }
            let v = sinpi_dd(x);
            let got = Float::with_val(250, v.high) + Float::with_val(250, v.low);
            let truth = Float::with_val(250, x).sin_pi();
            let abs = Float::with_val(250, &got - &truth).abs().to_f64();
            let ratio = abs / (SINPI_DD_EPS * v.high.abs());
            if ratio > worst {
                worst = ratio;
                worst_x = x;
            }
        }
        println!("sinpi dd tier: worst |err|/gate = {worst:.4} at x={worst_x:e}");
        assert!(
            worst < 0.5,
            "sinpi dd-tier gate covers only {:.2}× the slip at x={worst_x:e}",
            1.0 / worst
        );
    }

    /// Worst `|leg(x) − cos(πx)| / er(z)` for the cospi main-band leg, whose
    /// gate is CORE-MATH's residual-proportional `z·2⁻¹²³` plus the 2⁻⁷⁷
    /// absolute floor covering the table pair's own accuracy near grid
    /// points.  Value-uniform over `(2⁻¹², 4]`; `< 0.5` certifies the 2×
    /// margin.
    #[test]
    fn cospi_fast_leg_is_sound() {
        let mut worst = 0.0f64;
        let mut worst_x = 0.5;
        for i in 0..30_000_000u64 {
            let x = 2.44e-4 + mix(i) as f64 / (u64::MAX / 4) as f64;
            let ix = x.to_bits();
            let e = ((ix >> 52) & 0x7ff) as i64;
            let m = (ix & (u64::MAX >> 12)) | 1 << 52;
            let s = 1063 - e;
            let iq = ((((m >> s).wrapping_add(2048)) & 8191).wrapping_add(1)) >> 1;
            let k = m.wrapping_shl((e - 1000) as u32) as i64;
            let z = k as f64;
            let z2 = z * z;
            let fs = crate::fast_mul_add(
                z2,
                crate::fast_mul_add(z2, SINPI_ZS[2], SINPI_ZS[1]),
                SINPI_ZS[0],
            );
            let fc = crate::fast_mul_add(z2, SINPI_ZC[1], SINPI_ZC[0]);
            let (sg, cg) = sincosn(iq as i64);
            let er = crate::fast_mul_add(z.abs(), crate::exp2i(-123), crate::exp2i(-77));
            let r = crate::fast_mul_add(cg.high, z * fs, sg.low + sg.high * (z2 * fc));
            let got = Float::with_val(250, sg.high) + Float::with_val(250, r);
            let truth = Float::with_val(250, x).cos_pi();
            let abs = Float::with_val(250, &got - &truth).abs().to_f64();
            let ratio = abs / er;
            if ratio > worst {
                worst = ratio;
                worst_x = x;
            }
        }
        println!(
            "cospi fast leg: worst |err|/gate = {worst:.4} at x={worst_x:e} bits={:016x}",
            worst_x.to_bits()
        );
        assert!(
            worst < 0.5,
            "cospi gate covers only {:.2}× the slip at x={worst_x:e}",
            1.0 / worst
        );
    }

    /// Worst `|leg(x) − cos(πx)| / (x²·2⁻⁴⁷·⁵)` for the small band
    /// `(2⁻²⁶·⁵, 2⁻¹²]`, representation-uniform across its binades.
    #[test]
    fn cospi_small_band_is_sound() {
        let (lb, hb) = (0x3e2c_cf64_29be_6622u64, 0x3f30_0000_0000_0000);
        let mut worst = 0.0f64;
        let mut worst_x = 0.5;
        for i in 0..30_000_000u64 {
            let x = f64::from_bits(lb + mix(i) % (hb - lb + 1));
            let x2 = x * x;
            let x4 = x2 * x2;
            let eps = x2 * 8.659_739_592_076_221e-15;
            let p = x2
                * ((COSPI_SMALL_C[0] + x2 * COSPI_SMALL_C[1])
                    + x4 * (COSPI_SMALL_C[2] + x2 * COSPI_SMALL_C[3]));
            let got = Float::with_val(250, 1.0) + Float::with_val(250, p);
            let truth = Float::with_val(250, x).cos_pi();
            let abs = Float::with_val(250, &got - &truth).abs().to_f64();
            let ratio = abs / eps;
            if ratio > worst {
                worst = ratio;
                worst_x = x;
            }
        }
        println!("cospi small band: worst |err|/gate = {worst:.4} at x={worst_x:e}");
        assert!(
            worst < 0.5,
            "cospi small-band gate covers only {:.2}× the slip at x={worst_x:e}",
            1.0 / worst
        );
    }

    /// Worst relative `|cospi_dd(x) − cos(πx)| / (SINPI_DD_EPS·|high|)` over
    /// uniform and near-half-integer inputs (the fast leg's straddles).
    #[test]
    fn cospi_dd_tier_is_sound() {
        let mut worst = 0.0f64;
        let mut worst_x = 0.5;
        for i in 0..20_000_000u64 {
            let h = mix(i);
            let x = if i & 1 == 0 {
                h as f64 / (u64::MAX / 4) as f64
            } else {
                let k = ((h >> 32) % 8) as f64 + 0.5;
                let delta = f64::from_bits(0x3c90_0000_0000_0000 + (h & 0xF_FFFF_FFFF));
                if h & 16 == 0 { k + delta } else { k - delta }
            };
            if x == 0.0 || (2.0 * x).fract() == 0.0 {
                continue;
            }
            let v = cospi_dd(x);
            let got = Float::with_val(250, v.high) + Float::with_val(250, v.low);
            let truth = Float::with_val(250, x).cos_pi();
            let abs = Float::with_val(250, &got - &truth).abs().to_f64();
            let ratio = abs / (SINPI_DD_EPS * v.high.abs());
            if ratio > worst {
                worst = ratio;
                worst_x = x;
            }
        }
        println!("cospi dd tier: worst |err|/gate = {worst:.4} at x={worst_x:e}");
        assert!(
            worst < 0.5,
            "cospi dd-tier gate covers only {:.2}× the slip at x={worst_x:e}",
            1.0 / worst
        );
    }
}
